export const ICON_OPTIONS = Object.keys( ICON_PATHS ).map( ( key ) => ( {
	label: key,
	value: key,
} ) );

const ICON_VIEWBOX: Record< string, string > = {
	rocket: '0 0 22 22',
};

export function iconSvg( key: string, size = 24 ): string {
	const path = ICON_PATHS[ key ] || '';
	const viewBox = ICON_VIEWBOX[ key ] || '0 0 24 24';
	return `<svg width="${ size }" height="${ size }" viewBox="${ viewBox }" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ path }</svg>`;
}
